    /**
     * @method
     * @name hitbtc#fetchMarkets
     * @description retrieves data on all markets for hitbtc
     * @see https://api.hitbtc.com/#symbols
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public async override Task<List<ccxt.MarketInterface>> FetchMarkets(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> response = await this.publicGetPublicSymbol(parameters);
        //
        //     {
        //         "AAVEUSDT_PERP":{
        //             "type":"futures",
        //             "expiry":null,
        //             "underlying":"AAVE",
        //             "base_currency":null,
        //             "quote_currency":"USDT",
        //             "quantity_increment":"0.01",
        //             "tick_size":"0.001",
        //             "take_rate":"0.0005",
        //             "make_rate":"0.0002",
        //             "fee_currency":"USDT",
        //             "margin_trading":true,
        //             "max_initial_leverage":"50.00"
        //         },
        //         "MANAUSDT":{
        //             "type":"spot",
        //             "base_currency":"MANA",
        //             "quote_currency":"USDT",
        //             "quantity_increment":"1",
        //             "tick_size":"0.0000001",
        //             "take_rate":"0.0025",
        //             "make_rate":"0.001",
        //             "fee_currency":"USDT",
        //             "margin_trading":true,
        //             "max_initial_leverage":"5.00"
        //         },
        //     }
        //
        List<object> result = new List<object>() {};
        List<object> ids = new List<object>(((IDictionary<string,object>)response).Keys);
        for (int i = 0; i < ids.Count; i++)
        {
            string? id = ((string)ids[i]);
            if (id.EndsWith("_BQX"))
            {
                continue;
            }
            IDictionary<string, object> market = this.safeDict(response, id);
            string? marketType = this.safeString(market, "type");
            Int64? expiry = this.safeInteger(market, "expiry");
            bool contract = (marketType == "futures");
            bool spot = (marketType == "spot");
            bool? marginTrading = this.safeBool(market, "margin_trading", false);
            bool margin = spot && (marginTrading == true);
            bool future = ((expiry != null));
            bool swap = (contract && !future);
            bool option = false;
            string? baseId = this.safeString2(market, "base_currency", "underlying");
            string? quoteId = this.safeString(market, "quote_currency");
            string? feeCurrencyId = this.safeString(market, "fee_currency");
            string? bs = this.safeCurrencyCode(baseId);
            string? quote = this.safeCurrencyCode(quoteId);
            if (((bs == null)) || ((quote == null)))
            {
                continue;
            }
            string? feeCurrency = this.safeCurrencyCode(feeCurrencyId);
            string? settleId = null;
            string? settle = null;
            string symbol = ((bs + "/") + quote);
            string type = "spot";
            double? contractSize = null;
            bool? linear = null;
            bool? inverse = null;
            if (contract)
            {
                contractSize = this.parseNumber("1");
                settleId = feeCurrencyId;
                settle = this.safeCurrencyCode(settleId);
                linear = (((quote != null)) && ((quote == settle)));
                inverse = linear != true;
                symbol = ((symbol + ":") + settle);
                if (future)
                {
                    symbol = ((symbol + "-") + expiry);
                    type = "future";
                } else
                {
                    type = "swap";
                }
            }
            string? lotString = this.safeString(market, "quantity_increment");
            string? stepString = this.safeString(market, "tick_size");
            double? lot = this.parseNumber(lotString);
            double? step = this.parseNumber(stepString);
            result.Add(new Dictionary<string, object>() {
                { "id", id },
                { "symbol", symbol },
                { "base", bs },
                { "quote", quote },
                { "settle", settle },
                { "baseId", baseId },
                { "quoteId", quoteId },
                { "settleId", settleId },
                { "type", type },
                { "spot", spot },
                { "margin", margin },
                { "swap", swap },
                { "future", future },
                { "option", option },
                { "active", true },
                { "contract", contract },
                { "linear", linear },
                { "inverse", inverse },
                { "taker", this.safeNumber(market, "take_rate") },
                { "maker", this.safeNumber(market, "make_rate") },
                { "contractSize", contractSize },
                { "expiry", expiry },
                { "expiryDatetime", null },
                { "strike", null },
                { "optionType", null },
                { "feeCurrency", feeCurrency },
                { "precision", new Dictionary<string, object>() {
                    { "amount", lot },
                    { "price", step },
                } },
                { "limits", new Dictionary<string, object>() {
                    { "leverage", new Dictionary<string, object>() {
                        { "min", this.parseNumber("1") },
                        { "max", this.safeNumber(market, "max_initial_leverage", 1) },
                    } },
                    { "amount", new Dictionary<string, object>() {
                        { "min", lot },
                        { "max", null },
                    } },
                    { "price", new Dictionary<string, object>() {
                        { "min", step },
                        { "max", null },
                    } },
                    { "cost", new Dictionary<string, object>() {
                        { "min", this.parseNumber(Precise.stringMul(lotString, stepString)) },
                        { "max", null },
                    } },
                } },
                { "created", null },
                { "info", market },
            });
        }
        return ccxt.BaseExchange.ToMarketInterfaceList(result);
    }

    /**
     * @method
